INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(1550, 'point', '/pɔɪnt/', 'noun', '{"zh-TW":["要點；觀點","分數"],"en":["a key idea","a unit of scoring"]}', NULL, 'make a point / point out / turning point / to the point', '[{"en":"She made an excellent point in the meeting.","zh-TW":"她在會議上提出了很好的觀點。"},{"en":"I''d like to point out a few issues.","zh-TW":"我想指出幾個問題。"}]', '{"verb":"point","adjective":"pointed"}', NULL, 2, 1550),
(1551, 'policy', '/ˈpɒlɪsi/', 'noun', '{"zh-TW":["政策；方針"],"en":["a plan of action adopted by an organization"]}', '{"root":{"text":"poli","meaning":"city, state (國家)"}}', 'company policy / insurance policy / implement a policy', '[{"en":"The new policy takes effect next month.","zh-TW":"新政策下月生效。"},{"en":"It is against company policy to accept gifts.","zh-TW":"接受禮物違反公司政策。"}]', '{"noun":"policyholder"}', NULL, 2, 1551),
(1552, 'poll', '/poʊl/', 'noun', '{"zh-TW":["民調；投票","民調"],"en":["a survey of public opinion","a survey of opinion"]}', NULL, 'opinion poll / conduct a poll / go to the polls; opinion poll / exit poll / poll results', '[{"en":"The latest poll shows strong support.","zh-TW":"最新民調顯示強力支持。"},{"en":"We conducted a poll among employees.","zh-TW":"我們在員工中進行了調查。"},{"en":"According to the latest polls, support is growing.","zh-TW":"根據最新民調，支持率正在增長。"},{"en":"Exit polls predict a close race.","zh-TW":"出口民調預測競爭激烈。"}]', '{"noun":"pollster","verb":"poll"}', NULL, 1, 1552),
(1553, 'pool', '/puːl/', 'noun', '{"zh-TW":["資源池；共用資金"],"en":["a shared supply of resources"]}', NULL, 'pool resources / talent pool / car pool', '[{"en":"We need to pool our resources for this project.","zh-TW":"我們需要集中資源做這項目。"},{"en":"The company maintains a talent pool.","zh-TW":"公司維護人才庫。"}]', '{"verb":"pool"}', NULL, 1, 1553),
(1554, 'poor', '/pʊr/', 'adjective', '{"zh-TW":["貧窮的；差的"],"en":["having little money","of low quality"]}', NULL, 'poor performance / poor quality', '[{"en":"Poor performance will be addressed.","zh-TW":"差的表現會被處理。"},{"en":"Sales were poor this quarter.","zh-TW":"本季銷售表現不佳。"}]', '{"adjective":"poor","adverb":"poorly","noun":"poverty"}', NULL, 1, 1554),
(1555, 'popular', '/ˈpɒpjʊlər/', 'adjective', '{"zh-TW":["受歡迎的；流行的"],"en":["liked by many people"]}', NULL, 'popular demand / popular choice', '[{"en":"Due to popular demand, we extended the sale.","zh-TW":"由於廣受歡迎，我們延長了促銷。"},{"en":"This is our most popular product.","zh-TW":"這是我們最受歡迎的產品。"}]', '{"adjective":"popular","noun":"popularity","verb":"popularize","adjective2":"unpopular"}', NULL, 3, 1555),
(1556, 'portion', '/ˈpɔːrʃən/', 'noun', '{"zh-TW":["部分；份額"],"en":["a part of something"]}', '{"root":{"text":"port","meaning":"part (部分)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'a large portion / portion of the budget', '[{"en":"A large portion of the budget goes to salaries.","zh-TW":"預算的大部分用於薪資。"},{"en":"Each team receives an equal portion.","zh-TW":"每個團隊獲得相等份額。"}]', NULL, NULL, 3, 1556),
(1557, 'portrait', '/ˈpɔːrtrɪt/', 'noun', '{"zh-TW":["肖像；人像畫"],"en":["a painting or photograph of a person"]}', '{"prefix":{"text":"por-","meaning":"forth (向前)"},"root":{"text":"trait","meaning":"draw (描繪)"},"logic":"向前描繪出來的形象，即「肖像」。"}', 'portrait painting / family portrait', '[{"en":"The artist painted a portrait of the queen.","zh-TW":"藝術家為女王畫了一幅肖像。"},{"en":"A family portrait hung on the wall.","zh-TW":"一幅全家福掛在牆上。"}]', '{"noun":"portraiture","verb":"portray"}', NULL, 3, 1557),
(1558, 'pose', '/poʊz/', 'verb', '{"zh-TW":["構成；提出"],"en":["to present or constitute"]}', NULL, 'pose a threat / pose a question / pose a challenge', '[{"en":"This poses a serious threat to the business.","zh-TW":"這對業務構成嚴重威脅。"},{"en":"The new regulation poses challenges.","zh-TW":"新規定帶來挑戰。"}]', NULL, NULL, 1, 1558),
(1559, 'position', '/pəˈzɪʃən/', 'noun', '{"zh-TW":["職位","位置","立場"],"en":["a job","a place","an opinion"]}', '{"root":{"text":"posit","meaning":"place (放置)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'apply for a position / market position / bargaining position', '[{"en":"She applied for the managerial position.","zh-TW":"她申請了管理職位。"},{"en":"The company holds a strong market position.","zh-TW":"公司擁有強勁的市場地位。"}]', '{"verb":"position"}', NULL, 3, 1559),
(1560, 'positive', '/ˈpɒzɪtɪv/', 'adjective', '{"zh-TW":["積極的；正面的","肯定的","積極的","確定的"],"en":["good; constructive","certain; sure","certain"]}', '{"root":{"text":"posit","meaning":"place (放置)"},"suffix":{"text":"-ive","meaning":"...的"}}', 'positive feedback / positive impact / positive attitude; positive feedback / positive impact / test positive', '[{"en":"The feedback has been overwhelmingly positive.","zh-TW":"反饋非常正面。"},{"en":"A positive attitude makes a difference.","zh-TW":"積極態度會帶來改變。"},{"en":"A positive attitude makes a difference.","zh-TW":"積極的態度會帶來改變。"}]', '{"adverb":"positively","noun":"positivity"}', NULL, 3, 1560),
(1561, 'possess', '/pəˈzɛs/', 'verb', '{"zh-TW":["擁有；具有"],"en":["to have or own"]}', '{"prefix":{"text":"pos-","meaning":"able"},"root":{"text":"sess","meaning":"sit (坐)"}}', 'possess skills / possess the right / legally possess', '[{"en":"She possesses excellent leadership skills.","zh-TW":"她具備出色的領導力。"},{"en":"You must possess a valid ID to enter.","zh-TW":"進入須持有效證件。"}]', '{"noun":"possession","adjective":"possessive"}', NULL, 3, 1561),
(1562, 'possible', '/ˈpɒsɪbəl/', 'adjective', '{"zh-TW":["可能的"],"en":["able to be done or achieved"]}', NULL, 'as soon as possible / if possible', '[{"en":"Please reply as soon as possible.","zh-TW":"請盡快回覆。"},{"en":"We will deliver by Friday if possible.","zh-TW":"如果可能的話，我們週五前交貨。"}]', '{"adjective":"possible","noun":"possibility","adverb":"possibly","adjective2":"impossible"}', NULL, 3, 1562),
(1563, 'post', '/poʊst/', 'verb', '{"zh-TW":["張貼；公佈","郵寄"],"en":["to put up a notice","to send by mail"]}', NULL, 'post a notice / post online / post a letter', '[{"en":"The results will be posted on the website.","zh-TW":"結果將在網站上公佈。"},{"en":"Please post the documents today.","zh-TW":"請今天寄出文件。"}]', '{"noun":"post, postage, posting"}', NULL, 1, 1563),
(1564, 'postpone', '/poʊstˈpoʊn/', 'verb', '{"zh-TW":["延期；推遲"],"en":["to arrange for later than planned"]}', '{"prefix":{"text":"post-","meaning":"after (之後)"},"root":{"text":"pone","meaning":"put (放)"}}', 'postpone a meeting / postpone indefinitely', '[{"en":"The meeting has been postponed until Friday.","zh-TW":"會議已推遲到週五。"},{"en":"They decided to postpone the product launch.","zh-TW":"他們決定推遲產品發布。"}]', '{"noun":"postponement"}', NULL, 3, 1564),
(1565, 'potential', '/pəˈtenʃl/', 'noun', '{"zh-TW":["潛力；可能性","潛在的；可能的"],"en":["latent qualities that may be developed","possible; capable of becoming"]}', '{"root":{"text":"potent","meaning":"power (力量)"},"suffix":{"text":"-ial","meaning":"relating to (相關的)"},"logic":"與潛在力量相關的，即「潛力」。"}', 'reach one''s potential / growth potential / potential risk; potential risk / potential customer / growth potential', '[{"en":"She has the potential to become a great leader.","zh-TW":"她有潛力成為偉大的領導者。"},{"en":"We must consider the potential risks.","zh-TW":"我們必須考慮潛在風險。"},{"en":"There are potential risks in this investment.","zh-TW":"這項投資有潛在風險。"},{"en":"The market has great growth potential.","zh-TW":"市場有很大的成長潛力。"}]', '{"adjective":"potential","adverb":"potentially","noun":"potential, potentiality"}', NULL, 3, 1565),
(1566, 'pottery', '/ˈpɒtəri/', 'noun', '{"zh-TW":["陶器；陶藝"],"en":["objects made from baked clay"]}', '{"root":{"text":"pot","meaning":"pot (壺)"},"suffix":{"text":"-ery","meaning":"art/place of (技藝/場所)"},"logic":"製作壺器的技藝，即「陶藝」。"}', 'pottery class / pottery wheel', '[{"en":"She makes pottery as a hobby.","zh-TW":"她以製陶為嗜好。"},{"en":"Ancient pottery was found at the excavation site.","zh-TW":"挖掘現場發現了古代陶器。"}]', '{"noun":"potter"}', NULL, 3, 1566),
(1567, 'pour', '/pɔːr/', 'verb', '{"zh-TW":["倒；傾注","大量投入"],"en":["to flow or cause to flow","to invest heavily"]}', NULL, 'pour money into / pour resources into', '[{"en":"The company poured millions into R&D.","zh-TW":"公司投入數百萬於研發。"},{"en":"Orders have been pouring in since the launch.","zh-TW":"自發布以來訂單源源不斷。"}]', NULL, NULL, 1, 1567),
(1568, 'poverty', '/ˈpɒvərti/', 'noun', '{"zh-TW":["貧窮；貧困","貧窮"],"en":["the state of being very poor","the state of being poor"]}', NULL, 'poverty line / poverty rate / live in poverty; poverty level / reduce poverty', '[{"en":"The poverty rate has decreased.","zh-TW":"貧困率已下降。"},{"en":"Many families live below the poverty line.","zh-TW":"許多家庭生活在貧窮線以下。"},{"en":"Reducing poverty requires collective effort.","zh-TW":"減少貧困需要集體努力。"},{"en":"The poverty rate dropped by 3%.","zh-TW":"貧困率下降了3%。"}]', '{"adjective":"impoverished"}', NULL, 3, 1568),
(1569, 'power', '/ˈpaʊər/', 'noun', '{"zh-TW":["力量；權力；電力"],"en":["ability to act","authority","electricity"]}', NULL, 'purchasing power / power outage', '[{"en":"Consumer purchasing power has declined.","zh-TW":"消費者購買力下降了。"},{"en":"A power outage disrupted operations.","zh-TW":"停電影響了營運。"}]', '{"noun":"power","adjective":"powerful","adjective2":"powerless","verb":"empower"}', NULL, 2, 1569),
(1570, 'practice', '/ˈpræktɪs/', 'noun', '{"zh-TW":["實踐；慣例"],"en":["the actual doing of something; a habitual way"]}', NULL, 'best practice / put into practice / standard practice', '[{"en":"This is standard practice in our industry.","zh-TW":"這是我們行業的標準做法。"},{"en":"We put the theory into practice.","zh-TW":"我們將理論付諸實踐。"}]', '{"verb":"practice, practise","adjective":"practical","adverb":"practically","noun":"practitioner"}', NULL, 3, 1570),
(1571, 'precaution', '/prɪˈkɔːʃən/', 'noun', '{"zh-TW":["預防措施"],"en":["an action taken to prevent something bad"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"caution","meaning":"warning (警告)"}}', 'take precautions / safety precaution / as a precaution', '[{"en":"We take every precaution to ensure safety.","zh-TW":"我們採取一切預防措施確保安全。"},{"en":"As a precaution, please back up your files.","zh-TW":"作為預防，請備份文件。"}]', '{"adjective":"precautionary"}', NULL, 4, 1571),
(1572, 'precede', '/prɪˈsiːd/', 'verb', '{"zh-TW":["在...之前"],"en":["to come before in time or order"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"cede","meaning":"go (走)"}}', 'precede sth. / preceding year / as preceded by', '[{"en":"A brief introduction preceded the main speech.","zh-TW":"簡短介紹在主要演講之前。"},{"en":"In the preceding quarter, sales were strong.","zh-TW":"在前一季度，銷售強勁。"}]', '{"adjective":"preceding, precedent","noun":"precedent, precedence"}', NULL, 3, 1572),
(1573, 'precedent', '/ˈprɛsɪdənt/', 'noun', '{"zh-TW":["先例"],"en":["an earlier event or action used as an example"]}', NULL, 'set a precedent / legal precedent', '[{"en":"This case sets an important precedent.","zh-TW":"這個案件開創了重要的先例。"},{"en":"There is no precedent for this situation.","zh-TW":"這種情況沒有先例可循。"}]', '{"adjective":"unprecedented"}', NULL, 3, 1573),
(1574, 'precipitation', '/prɪˌsɪpɪˈteɪʃn/', 'noun', '{"zh-TW":["降水"],"en":["rain, snow, sleet, or hail that falls to the ground"]}', '{"prefix":{"text":"pre-","meaning":"before (前)"},"root":{"text":"cipit","meaning":"head/fall (頭/落下)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"頭朝下落下的過程，即「降水」。"}', 'annual precipitation / heavy precipitation', '[{"en":"The annual precipitation in this area is 1200mm.","zh-TW":"這個地區年降水量為1200毫米。"},{"en":"Heavy precipitation is expected overnight.","zh-TW":"預計夜間會有大量降水。"}]', '{"verb":"precipitate"}', NULL, 5, 1574),
(1575, 'precise', '/prɪˈsaɪs/', 'adjective', '{"zh-TW":["精確的；準確的"],"en":["exact and accurate"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"cise","meaning":"cut (切)"}}', 'precise measurement / to be precise / precise instructions', '[{"en":"Please give me the precise figures.","zh-TW":"請給我精確數據。"},{"en":"To be precise, the total is $45,231.","zh-TW":"準確地說，總數是$45,231。"}]', '{"adverb":"precisely","noun":"precision"}', NULL, 3, 1575),
(1576, 'predict', '/prɪˈdɪkt/', 'verb', '{"zh-TW":["預測","預測；預言"],"en":["to say what will happen in the future"]}', '{"prefix":{"text":"pre-","meaning":"before (在前)"},"root":{"text":"dict","meaning":"say (說)"},"logic":"事先說出，即「預測」。"}', 'predict the outcome / predict the future / hard to predict; predict the outcome / predict growth / as predicted', '[{"en":"Experts predict the economy will grow next year.","zh-TW":"專家預測明年經濟將成長。"},{"en":"It''s difficult to predict the weather accurately.","zh-TW":"精準預測天氣很困難。"},{"en":"Analysts predict strong growth next quarter.","zh-TW":"分析師預測下季度強勁增長。"},{"en":"It is difficult to predict market trends.","zh-TW":"很難預測市場趨勢。"}]', '{"noun":"prediction","adjective":"predictable","adverb":"predictably"}', NULL, 3, 1576),
(1577, 'predominant', '/prɪˈdɒmɪnənt/', 'adjective', '{"zh-TW":["主要的；佔優勢的"],"en":["most common or most powerful"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"domin","meaning":"rule (統治)"},"suffix":{"text":"-ant","meaning":"...的"}}', 'predominant factor / predominant view', '[{"en":"Cost is the predominant factor in their decision.","zh-TW":"成本是他們決定的主要因素。"},{"en":"English is the predominant language in business.","zh-TW":"英語是商務中的主要語言。"}]', '{"adverb":"predominantly","verb":"predominate"}', NULL, 4, 1577),
(1578, 'prefer', '/prɪˈfɜːr/', 'verb', '{"zh-TW":["偏好；更喜歡"],"en":["to like one thing more than another"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"fer","meaning":"carry (攜帶)"}}', 'prefer A to B / prefer to do', '[{"en":"Most clients prefer email communication.","zh-TW":"多數客戶偏好電郵溝通。"},{"en":"I prefer to work from home on Fridays.","zh-TW":"我偏好週五在家工作。"}]', '{"noun":"preference","adjective":"preferable, preferred","adverb":"preferably"}', NULL, 2, 1578),
(1579, 'preliminary', '/prɪˈlɪmɪneri/', 'adjective', '{"zh-TW":["初步的；預備的"],"en":["coming before the main part"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"limin","meaning":"threshold (門檻)"}}', 'preliminary results / preliminary investigation', '[{"en":"Preliminary results indicate success.","zh-TW":"初步結果顯示成功。"},{"en":"A preliminary review was conducted.","zh-TW":"進行了初步審查。"}]', '{"noun":"preliminary"}', NULL, 4, 1579),
(1580, 'premiere', '/prɪˈmɪər/', 'noun', '{"zh-TW":["首映；首演"],"en":["the first public showing of a movie or performance"]}', '{"prefix":{"text":"pre-","meaning":"first (第一)"},"root":{"text":"miere","meaning":"first (最初)"},"logic":"最初的公開展演，即「首映」。"}', 'movie premiere / world premiere', '[{"en":"The movie premiere attracted many celebrities.","zh-TW":"電影首映吸引了許多名人。"},{"en":"The play had its world premiere in London.","zh-TW":"這齣戲在倫敦舉行了世界首演。"}]', '{"verb":"premiere"}', NULL, 3, 1580),
(1581, 'premise', '/ˈprɛmɪs/', 'noun', '{"zh-TW":["前提","場所"],"en":["a statement assumed to be true","a building and its land"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"mis","meaning":"send (送)"}}', 'on the premise that / business premises', '[{"en":"The plan is based on the premise that sales will grow.","zh-TW":"計劃以銷售將增長為前提。"},{"en":"Smoking is not allowed on the premises.","zh-TW":"場所內禁止吸煙。"}]', NULL, NULL, 3, 1581),
(1582, 'premium', '/ˈpriːmiəm/', 'noun', '{"zh-TW":["保費","額外費用","優質的"],"en":["an insurance payment","an extra charge","of high quality"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"em","meaning":"buy (買)"}}', 'insurance premium / premium quality / at a premium', '[{"en":"Insurance premiums have increased this year.","zh-TW":"今年保費增加了。"},{"en":"Office space is available at a premium.","zh-TW":"辦公空間以高價提供。"}]', NULL, NULL, 3, 1582),
(1583, 'preparation', '/ˌprɛpəˈreɪʃən/', 'noun', '{"zh-TW":["準備；籌備"],"en":["the process of getting ready"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"par","meaning":"make ready (準備)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'in preparation for / make preparations', '[{"en":"The team is making preparations for the launch.","zh-TW":"團隊正在為發布做準備。"},{"en":"In preparation for the audit, please organize files.","zh-TW":"為準備審計，請整理文件。"}]', '{"verb":"prepare","adjective":"preparatory"}', NULL, 4, 1583),
(1584, 'prepare', '/prɪˈpɛr/', 'verb', '{"zh-TW":["準備"],"en":["to make ready for use or an event"]}', NULL, 'prepare for / well-prepared', '[{"en":"Please prepare the report by Monday.","zh-TW":"請在週一前準備好報告。"},{"en":"We are well-prepared for the audit.","zh-TW":"我們為審計做了充分準備。"}]', '{"verb":"prepare","noun":"preparation","adjective":"prepared"}', NULL, 3, 1584),
(1585, 'prescribe', '/prɪˈskraɪb/', 'verb', '{"zh-TW":["規定；指示"],"en":["to state officially what should be done"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"scribe","meaning":"write (寫)"}}', 'prescribed by law / prescribed procedures', '[{"en":"The law prescribes strict penalties.","zh-TW":"法律規定了嚴格的處罰。"},{"en":"Follow the prescribed procedures.","zh-TW":"遵循規定的程序。"}]', '{"noun":"prescription","adjective":"prescribed"}', NULL, 3, 1585),
(1586, 'presence', '/ˈprɛzəns/', 'noun', '{"zh-TW":["存在；出席","風範"],"en":["the state of being present","a person''s bearing"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"sens","meaning":"be (存在)"}}', 'in the presence of / online presence / market presence', '[{"en":"The company has a strong online presence.","zh-TW":"公司有強大的線上存在感。"},{"en":"Your presence at the meeting is required.","zh-TW":"你需出席會議。"}]', '{"adjective":"present","verb":"present"}', NULL, 3, 1586),
(1587, 'present', '/prɪˈzɛnt/', 'verb', '{"zh-TW":["呈現；提出","介紹"],"en":["to show or offer","to introduce"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"sent","meaning":"be (存在)"}}', 'present a proposal / present findings / present an opportunity', '[{"en":"She presented her findings to the board.","zh-TW":"她向董事會呈現了研究結果。"},{"en":"This presents a unique opportunity.","zh-TW":"這提供了獨特機會。"}]', '{"noun":"presentation, presenter, present","adjective":"present, presentable"}', NULL, 3, 1587),
(1588, 'preserve', '/prɪˈzɜːrv/', 'verb', '{"zh-TW":["保存；維護"],"en":["to keep in its original state","to keep safe or maintain"]}', '{"prefix":{"text":"pre-","meaning":"before (預先)"},"root":{"text":"serve","meaning":"keep (保持)"},"logic":"預先保持好，即「保存」。"}', 'preserve wildlife / preserve tradition / well-preserved; preserve the environment / preserve quality', '[{"en":"We must preserve our natural resources.","zh-TW":"我們必須保存自然資源。"},{"en":"The old building has been well preserved.","zh-TW":"這棟老建築保存得很好。"},{"en":"We must preserve the quality of our products.","zh-TW":"我們必須維護產品品質。"},{"en":"Efforts to preserve the environment are ongoing.","zh-TW":"保護環境的努力仍在進行。"}]', '{"noun":"preservation"}', NULL, 3, 1588),
(1589, 'preside', '/prɪˈzaɪd/', 'verb', '{"zh-TW":["主持；主管"],"en":["to be in charge of a meeting"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"side","meaning":"sit (坐)"}}', 'preside over / preside at a meeting', '[{"en":"The chairman presided over the meeting.","zh-TW":"主席主持了會議。"},{"en":"She presides over a team of 50.","zh-TW":"她管理50人的團隊。"}]', '{"noun":"president, presidency","adjective":"presidential"}', NULL, 3, 1589),
(1590, 'press', '/prɛs/', 'verb', '{"zh-TW":["按壓","催促","新聞界"],"en":["to push","to urge","media"]}', NULL, 'press a button / press conference / press for', '[{"en":"Press the button to start the machine.","zh-TW":"按按鈕啟動機器。"},{"en":"The union is pressing for higher wages.","zh-TW":"工會正在爭取更高工資。"}]', '{"noun":"press, pressure","adjective":"pressing"}', NULL, 2, 1590),
(1591, 'pressure', '/ˈprɛʃər/', 'noun', '{"zh-TW":["壓力"],"en":["the force exerted; stress"]}', '{"root":{"text":"press","meaning":"push (推)"},"suffix":{"text":"-ure","meaning":"行為"}}', 'under pressure / put pressure on / peer pressure', '[{"en":"The team is under pressure to meet deadlines.","zh-TW":"團隊有趕截止日期的壓力。"},{"en":"Don''t put too much pressure on yourself.","zh-TW":"別給自己太大壓力。"}]', '{"verb":"pressure, pressurize"}', NULL, 3, 1591),
(1592, 'presume', '/prɪˈzjuːm/', 'verb', '{"zh-TW":["假定；推測"],"en":["to suppose; to assume"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"sume","meaning":"take (拿)"}}', 'presume that / be presumed to / presumably', '[{"en":"I presume you have read the report.","zh-TW":"我假定你已讀了報告。"},{"en":"He is presumed to be responsible.","zh-TW":"他被認為應負責。"}]', '{"noun":"presumption","adjective":"presumptuous","adverb":"presumably"}', NULL, 3, 1592),
(1593, 'pretty', '/ˈprɪti/', 'adverb', '{"zh-TW":["相當；漂亮的"],"en":["to a moderately high degree","attractive"]}', NULL, 'pretty good / pretty much', '[{"en":"The results are pretty good.","zh-TW":"結果相當不錯。"},{"en":"We are pretty much done.","zh-TW":"我們差不多完成了。"}]', '{"adjective":"pretty","adverb":"pretty"}', NULL, 2, 1593),
(1594, 'prevail', '/prɪˈveɪl/', 'verb', '{"zh-TW":["盛行；獲勝"],"en":["to be widespread; to win"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"vail","meaning":"be strong (強大)"}}', 'prevailing conditions / prevail upon / justice prevails', '[{"en":"Common sense prevailed in the end.","zh-TW":"最終常識佔了上風。"},{"en":"Such attitudes still prevail in some companies.","zh-TW":"這種態度在一些公司仍盛行。"}]', '{"adjective":"prevailing, prevalent","noun":"prevalence"}', NULL, 3, 1594),
(1595, 'prevent', '/prɪˈvent/', 'verb', '{"zh-TW":["預防；阻止","防止；阻止"],"en":["to stop something from happening"]}', '{"prefix":{"text":"pre-","meaning":"before (在前)"},"root":{"text":"vent","meaning":"come (來)"},"logic":"在某事來臨前阻止，即「預防」。"}', 'prevent accidents / prevent disease / prevent from; prevent sth. from happening / prevent damage', '[{"en":"Regular exercise helps prevent heart disease.","zh-TW":"規律運動有助預防心臟病。"},{"en":"The barrier prevents people from falling.","zh-TW":"護欄防止人跌落。"},{"en":"We must prevent this from happening again.","zh-TW":"我們必須防止這再次發生。"},{"en":"Regular maintenance prevents costly repairs.","zh-TW":"定期維護防止昂貴的維修。"}]', '{"noun":"prevention","adjective":"preventive"}', NULL, 3, 1595),
(1596, 'previous', '/ˈpriːviəs/', 'adjective', '{"zh-TW":["先前的；以前的"],"en":["happening before the current time"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"vi","meaning":"way (路)"}}', 'previous experience / previous year / previous employer', '[{"en":"Do you have any previous experience?","zh-TW":"你有先前的經驗嗎？"},{"en":"Sales increased compared to the previous year.","zh-TW":"銷售比前一年增加了。"}]', '{"adverb":"previously"}', NULL, 3, 1596),
(1597, 'price', '/praɪs/', 'noun', '{"zh-TW":["價格"],"en":["the amount of money for which something is sold"]}', '{"root":{"text":"price","meaning":"value (價值)"},"logic":"源自拉丁語 pretium（價值）。"}', 'price tag / asking price / price range', '[{"en":"The price of gas has gone up again.","zh-TW":"汽油價格又上漲了。"},{"en":"What is the price of this laptop?","zh-TW":"這台筆電的價格是多少？"}]', '{"adjective":"pricey","verb":"price"}', NULL, 2, 1597),
(1598, 'primarily', '/praɪˈmɛrəli/', 'adverb', '{"zh-TW":["主要地"],"en":["mainly; for the most part"]}', '{"root":{"text":"prim","meaning":"first (第一)"},"suffix":{"text":"-arily","meaning":"副詞後綴"}}', 'primarily responsible / primarily focused on', '[{"en":"The company primarily focuses on B2B services.","zh-TW":"公司主要專注於B2B服務。"},{"en":"She is primarily responsible for marketing.","zh-TW":"她主要負責行銷。"}]', '{"adjective":"primary"}', NULL, 3, 1598),
(1599, 'primary', '/ˈpraɪmeri/', 'adjective', '{"zh-TW":["主要的；首要的"],"en":["most important; main"]}', '{"root":{"text":"prim","meaning":"first (第一)"},"suffix":{"text":"-ary","meaning":"...的"}}', 'primary goal / primary source / primary concern', '[{"en":"Our primary goal is customer satisfaction.","zh-TW":"我們的首要目標是客戶滿意。"},{"en":"Cost reduction is the primary concern.","zh-TW":"降低成本是首要關注。"}]', '{"adverb":"primarily"}', NULL, 3, 1599);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(1600, 'principal', '/ˈprɪnsɪpəl/', 'adjective', '{"zh-TW":["主要的；首要的"],"en":["most important"]}', '{"root":{"text":"princip","meaning":"first (第一)"},"suffix":{"text":"-al","meaning":"...的"}}', 'principal reason / principal investor', '[{"en":"The principal reason for the delay was funding.","zh-TW":"延遲的主要原因是資金。"},{"en":"She is the principal investor in the company.","zh-TW":"她是公司的主要投資者。"}]', '{"adverb":"principally","noun":"principal"}', NULL, 3, 1600),
(1601, 'principle', '/ˈprɪnsɪpəl/', 'noun', '{"zh-TW":["原則；原理"],"en":["a fundamental truth or rule"]}', '{"root":{"text":"princip","meaning":"first (第一)"}}', 'in principle / basic principle / guiding principle', '[{"en":"In principle, we agree with the proposal.","zh-TW":"原則上我們同意提案。"},{"en":"The company operates on ethical principles.","zh-TW":"公司按道德原則運營。"}]', '{"adjective":"principled"}', NULL, 3, 1601),
(1602, 'prior', '/ˈpraɪər/', 'adjective', '{"zh-TW":["先前的；優先的"],"en":["existing or happening before"]}', '{"root":{"text":"pri","meaning":"before (之前)"}}', 'prior to / prior experience / prior approval', '[{"en":"Prior experience is required for this role.","zh-TW":"這職位需要先前經驗。"},{"en":"Prior to the merger, the company was smaller.","zh-TW":"合併前公司較小。"}]', '{"noun":"priority","verb":"prioritize"}', NULL, 2, 1602),
(1603, 'priority', '/praɪˈɒrəti/', 'noun', '{"zh-TW":["優先事項"],"en":["something regarded as more important than others","something more important than others"]}', '{"root":{"text":"prior","meaning":"before/first (在前/首先)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"排在前面的事項，即「優先事項」。"}', 'top priority / give priority to / set priorities', '[{"en":"Safety is our top priority.","zh-TW":"安全是我們的首要之務。"},{"en":"You need to set your priorities.","zh-TW":"你需要排定優先順序。"},{"en":"Customer safety is our top priority.","zh-TW":"客戶安全是首要之務。"}]', '{"verb":"prioritize","adjective":"prior"}', NULL, 3, 1603),
(1604, 'privacy', '/ˈpraɪvəsi/', 'noun', '{"zh-TW":["隱私"],"en":["the state of being free from public attention"]}', '{"root":{"text":"priv","meaning":"separate (分離)"},"suffix":{"text":"-acy","meaning":"狀態"}}', 'privacy policy / invasion of privacy / protect privacy', '[{"en":"We take customer privacy seriously.","zh-TW":"我們重視客戶隱私。"},{"en":"Read our privacy policy for more details.","zh-TW":"閱讀我們的隱私政策。"}]', '{"adjective":"private","adverb":"privately"}', NULL, 3, 1604),
(1605, 'privilege', '/ˈprɪvɪlɪdʒ/', 'noun', '{"zh-TW":["特權；榮幸"],"en":["a special right or advantage"]}', '{"root":{"text":"priv","meaning":"private (私人)"},"suffix":{"text":"-lege","meaning":"law (法律)"}}', 'executive privilege / it is a privilege to', '[{"en":"It''s a privilege to work with this team.","zh-TW":"與這團隊合作是榮幸。"},{"en":"Access to the lounge is a member privilege.","zh-TW":"進入貴賓室是會員特權。"}]', '{"adjective":"privileged"}', NULL, 3, 1605),
(1606, 'probe', '/proʊb/', 'verb', '{"zh-TW":["探查；調查"],"en":["to investigate thoroughly"]}', NULL, 'probe into / probe the issue', '[{"en":"Investigators probed into the financial fraud.","zh-TW":"調查人員深入調查財務詐欺。"},{"en":"The committee probed the matter further.","zh-TW":"委員會進一步調查此事。"}]', '{"noun":"probe"}', NULL, 2, 1606),
(1607, 'problem', '/ˈprɒbləm/', 'noun', '{"zh-TW":["問題"],"en":["a matter that is difficult to deal with"]}', NULL, 'solve a problem / no problem', '[{"en":"We need to solve this problem quickly.","zh-TW":"我們需要快速解決這個問題。"},{"en":"No problem, I can handle it.","zh-TW":"沒問題，我可以處理。"}]', '{"noun":"problem","adjective":"problematic"}', NULL, 3, 1607),
(1608, 'proceed', '/prəˈsiːd/', 'verb', '{"zh-TW":["繼續進行","繼續；進行"],"en":["to continue with an action","to continue; to go forward"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"ceed","meaning":"go (走)"},"logic":"向前走，即「繼續進行」。"}', 'proceed with / proceed to / proceed as planned', '[{"en":"Please proceed to the next step.","zh-TW":"請繼續下一步。"},{"en":"The project will proceed as planned.","zh-TW":"專案將按計畫進行。"},{"en":"We will proceed with the plan as scheduled.","zh-TW":"我們將按計劃進行。"}]', '{"noun":"procedure","noun2":"proceedings","adjective":"procedural"}', NULL, 3, 1608),
(1609, 'process', '/ˈprɒsɛs/', 'noun', '{"zh-TW":["過程；流程"],"en":["a series of steps; a method"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"cess","meaning":"go (走)"}}', 'hiring process / in the process of / streamline the process', '[{"en":"The hiring process takes about two weeks.","zh-TW":"招聘流程約需兩週。"},{"en":"We are in the process of upgrading the system.","zh-TW":"我們正在升級系統。"}]', '{"verb":"process","noun":"processing, processor"}', NULL, 3, 1609),
(1610, 'processor', '/ˈprɒsɛsər/', 'noun', '{"zh-TW":["處理器"],"en":["the part of a computer that performs operations"]}', NULL, 'word processor / multi-core processor', '[{"en":"This laptop has a fast processor.","zh-TW":"這台筆電有一顆快速處理器。"},{"en":"The processor handles millions of calculations.","zh-TW":"處理器處理數百萬次運算。"}]', '{"verb":"process"}', NULL, 3, 1610),
(1611, 'procure', '/prəˈkjʊr/', 'verb', '{"zh-TW":["獲得；採購"],"en":["to obtain, especially with effort"]}', '{"prefix":{"text":"pro-","meaning":"for"},"root":{"text":"cure","meaning":"care (照料)"}}', 'procure supplies / procure funding', '[{"en":"The department procures supplies from local vendors.","zh-TW":"部門從當地供應商採購物資。"},{"en":"We need to procure additional funding.","zh-TW":"我們需要取得額外資金。"}]', '{"noun":"procurement"}', NULL, 3, 1611),
(1612, 'procurement', '/prəˈkjʊrmənt/', 'noun', '{"zh-TW":["採購"],"en":["the process of obtaining goods or services"]}', NULL, 'procurement department / public procurement', '[{"en":"The procurement department handles all purchasing.","zh-TW":"採購部門處理所有購買事宜。"},{"en":"Public procurement must follow strict rules.","zh-TW":"公共採購必須遵循嚴格的規定。"}]', '{"noun":"procurement","verb":"procure"}', NULL, 4, 1612),
(1613, 'produce', '/ˈprɒdjuːs/', 'noun', '{"zh-TW":["農產品","生產；製造","產生"],"en":["fresh fruits and vegetables","to make or manufacture","to cause"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"duce","meaning":"lead (引導)"},"logic":"向前引導出來的東西，即「產出」。"}', 'fresh produce / local produce; produce goods / produce results / mass-produce', '[{"en":"The supermarket has a large produce section.","zh-TW":"這間超市有很大的生鮮蔬果區。"},{"en":"We buy organic produce from local farms.","zh-TW":"我們從本地農場購買有機農產品。"},{"en":"The factory produces 10,000 units per day.","zh-TW":"工廠每天生產一萬件。"},{"en":"The campaign produced excellent results.","zh-TW":"活動產生了優秀的結果。"}]', '{"verb":"produce","noun":"production","adjective":"productive"}', NULL, 3, 1613),
(1614, 'product', '/ˈprɒdʌkt/', 'noun', '{"zh-TW":["產品"],"en":["something that is manufactured for sale"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"duct","meaning":"lead (引導)"},"logic":"被引導出來的東西，即「產品」。"}', 'new product / product launch', '[{"en":"This product is our best seller.","zh-TW":"這個產品是我們的暢銷品。"},{"en":"The company launched a new product line.","zh-TW":"公司推出了新的產品線。"}]', '{"noun":"production","verb":"produce","adjective":"productive"}', NULL, 3, 1614),
(1615, 'productive', '/prəˈdʌktɪv/', 'adjective', '{"zh-TW":["有生產力的；多產的"],"en":["producing good results"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"duct","meaning":"lead (引導)"},"suffix":{"text":"-ive","meaning":"...的"}}', 'productive meeting / highly productive', '[{"en":"It was a very productive meeting.","zh-TW":"這是一個非常有成效的會議。"},{"en":"The team has been highly productive.","zh-TW":"團隊生產力很高。"}]', '{"noun":"productivity","adverb":"productively"}', NULL, 4, 1615),
(1616, 'profession', '/prəˈfɛʃən/', 'noun', '{"zh-TW":["職業；專業"],"en":["a type of job requiring special training"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"fess","meaning":"declare (宣稱)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'by profession / medical profession / enter a profession', '[{"en":"She is a lawyer by profession.","zh-TW":"她的職業是律師。"},{"en":"He entered the teaching profession.","zh-TW":"他進入了教學行業。"}]', '{"adjective":"professional","adverb":"professionally","noun":"professional"}', NULL, 4, 1616),
(1617, 'professor', '/prəˈfɛsər/', 'noun', '{"zh-TW":["教授"],"en":["a senior university teacher"]}', NULL, 'assistant professor / professor of history', '[{"en":"The professor published a new paper.","zh-TW":"教授發表了一篇新論文。"},{"en":"She''s a professor of biology.","zh-TW":"她是生物學教授。"}]', NULL, NULL, 3, 1617),
(1618, 'profile', '/ˈproʊfaɪl/', 'noun', '{"zh-TW":["簡介；概況","形象"],"en":["a description of characteristics","public image"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"fil","meaning":"thread, line (線)"}}', 'company profile / high-profile / raise one''s profile', '[{"en":"Please update your employee profile.","zh-TW":"請更新你的員工資料。"},{"en":"The company maintains a high profile in the industry.","zh-TW":"公司在業界保持高知名度。"}]', '{"verb":"profile","adjective":"high-profile, low-profile"}', NULL, 3, 1618),
(1619, 'profit', '/ˈprɒfɪt/', 'noun', '{"zh-TW":["利潤；收益"],"en":["money gained from business"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"fit","meaning":"make (做)"}}', 'net profit / profit margin / make a profit', '[{"en":"The company made a profit of $1 million.","zh-TW":"公司獲利一百萬美元。"},{"en":"Profit margins have been shrinking.","zh-TW":"利潤率一直在縮減。"}]', '{"adjective":"profitable","noun":"profitability","verb":"profit"}', NULL, 2, 1619),
(1620, 'profound', '/prəˈfaʊnd/', 'adjective', '{"zh-TW":["深刻的；深遠的"],"en":["very great or intense"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"found","meaning":"bottom (底部)"}}', 'profound impact / profound effect / profound change', '[{"en":"Technology has had a profound impact on business.","zh-TW":"科技對商業有深遠影響。"},{"en":"The changes are profound and lasting.","zh-TW":"這些變化是深刻且持久的。"}]', '{"adverb":"profoundly","noun":"profundity"}', NULL, 3, 1620),
(1621, 'program', '/ˈproʊɡræm/', 'noun', '{"zh-TW":["計劃；方案","程式"],"en":["a planned series of activities","software"]}', NULL, 'training program / program development / government program', '[{"en":"The company launched a new training program.","zh-TW":"公司推出了新培訓計劃。"},{"en":"She manages the employee wellness program.","zh-TW":"她管理員工健康方案。"}]', '{"verb":"program","noun":"programmer, programming"}', NULL, 3, 1621),
(1622, 'progress', '/ˈprɒɡrɛs/', 'noun', '{"zh-TW":["進展；進步"],"en":["forward movement; development"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"gress","meaning":"step (步)"}}', 'make progress / in progress / progress report', '[{"en":"We have made significant progress this month.","zh-TW":"本月我們取得了重大進展。"},{"en":"The project is still in progress.","zh-TW":"項目仍在進行中。"}]', '{"verb":"progress","adjective":"progressive","adverb":"progressively"}', NULL, 3, 1622),
(1623, 'prohibit', '/prəˈhɪbɪt/', 'verb', '{"zh-TW":["禁止"],"en":["to officially forbid","to officially ban"]}', '{"prefix":{"text":"pro-","meaning":"before"},"root":{"text":"hibit","meaning":"hold (持有)"}}', 'prohibit sb. from / strictly prohibited; strictly prohibited / prohibited by law', '[{"en":"Smoking is prohibited in all buildings.","zh-TW":"所有建築物內禁止吸煙。"},{"en":"The law prohibits discrimination.","zh-TW":"法律禁止歧視。"},{"en":"Photography is strictly prohibited.","zh-TW":"嚴禁拍照。"},{"en":"The use of mobile phones is prohibited.","zh-TW":"禁止使用手機。"}]', '{"noun":"prohibition","adjective":"prohibitive"}', NULL, 3, 1623),
(1624, 'project', '/ˈprɒdʒɛkt/', 'noun', '{"zh-TW":["專案；項目"],"en":["a planned piece of work"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"ject","meaning":"throw (投擲)"}}', 'project management / project deadline / project team', '[{"en":"The project is expected to be completed by June.","zh-TW":"項目預計六月完成。"},{"en":"She leads a team of five on the project.","zh-TW":"她帶領五人團隊做該項目。"}]', '{"verb":"project","noun":"projection, projector"}', NULL, 3, 1624),
(1625, 'prolong', '/prəˈlɒŋ/', 'verb', '{"zh-TW":["延長；拖延"],"en":["to make something last longer"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"long","meaning":"long (長)"}}', 'prolong the discussion / prolonged period', '[{"en":"We should not prolong the negotiations.","zh-TW":"我們不應拖延談判。"},{"en":"The prolonged delay caused concern.","zh-TW":"長期延誤引起了擔憂。"}]', '{"adjective":"prolonged","noun":"prolongation"}', NULL, 3, 1625),
(1626, 'prominent', '/ˈprɒmɪnənt/', 'adjective', '{"zh-TW":["傑出的；顯著的"],"en":["important; well-known"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"min","meaning":"project (突出)"},"suffix":{"text":"-ent","meaning":"...的"}}', 'prominent figure / prominent role / prominently displayed', '[{"en":"She is a prominent figure in the industry.","zh-TW":"她是業界的傑出人物。"},{"en":"The brand is prominently displayed.","zh-TW":"品牌被醒目地展示。"}]', '{"adverb":"prominently","noun":"prominence"}', NULL, 3, 1626),
(1627, 'promise', '/ˈprɒmɪs/', 'verb', '{"zh-TW":["承諾；保證"],"en":["to tell someone you will do something"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"mis","meaning":"send (送)"}}', 'make a promise / promise to do / show promise', '[{"en":"The company promised to deliver by Monday.","zh-TW":"公司承諾週一前送達。"},{"en":"The new employee shows great promise.","zh-TW":"新員工展現出很大潛力。"}]', '{"noun":"promise","adjective":"promising"}', NULL, 3, 1627),
(1628, 'promote', '/prəˈmoʊt/', 'verb', '{"zh-TW":["促進；推廣","晉升"],"en":["to help something develop","to give higher rank"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"mote","meaning":"move (移動)"}}', 'promote a product / get promoted / promote growth', '[{"en":"She was promoted to senior manager.","zh-TW":"她被晉升為高級經理。"},{"en":"We need to promote the new product line.","zh-TW":"我們需要推廣新產品線。"}]', '{"noun":"promotion, promoter","adjective":"promotional"}', NULL, 3, 1628),
(1629, 'promotion', '/prəˈmoʊʃn/', 'noun', '{"zh-TW":["促銷；升遷"],"en":["advertising activity","advancement in rank or position"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"mot","meaning":"move (移動)"},"suffix":{"text":"-ion","meaning":"act of (行為)"},"logic":"向前推動的行為，即「促銷」或「升遷」。"}', 'sales promotion / get a promotion', '[{"en":"The store is running a buy-one-get-one promotion.","zh-TW":"商店正在舉辦買一送一的促銷活動。"},{"en":"She received a promotion to senior manager.","zh-TW":"她被升為資深經理。"}]', '{"verb":"promote","adjective":"promotional"}', NULL, 3, 1629),
(1630, 'prompt', '/prɒmpt/', 'adjective', '{"zh-TW":["迅速的；及時的"],"en":["done quickly; immediate"]}', NULL, 'prompt response / prompt delivery / prompt action', '[{"en":"Thank you for your prompt response.","zh-TW":"感謝你的迅速回覆。"},{"en":"Prompt action is required.","zh-TW":"需要立即行動。"}]', '{"adverb":"promptly","verb":"prompt","noun":"promptness"}', NULL, 2, 1630),
(1631, 'proof', '/pruːf/', 'noun', '{"zh-TW":["證據；證明"],"en":["evidence that shows something is true"]}', NULL, 'proof of identity / burden of proof / proof of purchase', '[{"en":"You need proof of identity to open an account.","zh-TW":"開戶需要身分證明。"},{"en":"Keep the receipt as proof of purchase.","zh-TW":"保留收據作為購買證明。"}]', '{"verb":"prove","adjective":"proven"}', NULL, 2, 1631),
(1632, 'proper', '/ˈprɒpər/', 'adjective', '{"zh-TW":["適當的；正確的"],"en":["suitable; correct"]}', NULL, 'proper procedure / proper way / proper training', '[{"en":"Please follow the proper procedure.","zh-TW":"請遵循適當程序。"},{"en":"All staff must receive proper training.","zh-TW":"所有員工須接受適當培訓。"}]', '{"adverb":"properly"}', NULL, 2, 1632),
(1633, 'property', '/ˈprɒpərti/', 'noun', '{"zh-TW":["財產；房產","特性"],"en":["something owned","a characteristic"]}', '{"root":{"text":"propri","meaning":"own (擁有)"},"suffix":{"text":"-ty","meaning":"狀態"}}', 'intellectual property / property management / property value', '[{"en":"The company owns several properties downtown.","zh-TW":"公司在市中心擁有幾處房產。"},{"en":"Intellectual property must be protected.","zh-TW":"智慧財產權必須受到保護。"}]', NULL, NULL, 3, 1633),
(1634, 'proportion', '/prəˈpɔːrʃən/', 'noun', '{"zh-TW":["比例；部分","比例"],"en":["a part of a whole; ratio","a part considered in relation to the whole"]}', '{"prefix":{"text":"pro-","meaning":"for"},"root":{"text":"portion","meaning":"part (部分)"}}', 'in proportion to / a large proportion / out of proportion; in proportion / a high proportion / out of proportion', '[{"en":"A large proportion of the budget goes to R&D.","zh-TW":"預算的大部分用於研發。"},{"en":"Salary should be in proportion to experience.","zh-TW":"薪資應與經驗成比例。"},{"en":"A high proportion of staff are part-time.","zh-TW":"很高比例的員工是兼職的。"},{"en":"Keep expenses in proportion to revenue.","zh-TW":"使支出與收入成比例。"}]', '{"adjective":"proportional, proportionate","adverb":"proportionally"}', NULL, 4, 1634),
(1635, 'proposal', '/prəˈpoʊzəl/', 'noun', '{"zh-TW":["提案；建議"],"en":["a formal suggestion or plan"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"pos","meaning":"put (放)"},"suffix":{"text":"-al","meaning":"名詞後綴"}}', 'submit a proposal / business proposal / accept a proposal', '[{"en":"The board approved the merger proposal.","zh-TW":"董事會批准了合併提案。"},{"en":"Please submit your proposal by Friday.","zh-TW":"請於週五前提交提案。"}]', '{"verb":"propose","noun":"proposer"}', NULL, 3, 1635),
(1636, 'propose', '/prəˈpoʊz/', 'verb', '{"zh-TW":["提議；求婚","提議；建議"],"en":["to suggest a plan or idea"]}', '{"prefix":{"text":"pro-","meaning":"forward (向前)"},"root":{"text":"pose","meaning":"put (放置)"},"logic":"把想法放到前面來，即「提議」。"}', 'propose a plan / propose changes / propose a solution; propose a plan / propose changes / propose that', '[{"en":"I propose we postpone the meeting.","zh-TW":"我提議我們延後會議。"},{"en":"She proposed several changes to the plan.","zh-TW":"她對計畫提出了幾項修改建議。"},{"en":"I propose that we postpone the meeting.","zh-TW":"我提議我們推遲會議。"},{"en":"She proposed a new marketing strategy.","zh-TW":"她提出了新的行銷策略。"}]', '{"noun":"proposal"}', NULL, 3, 1636),
(1637, 'prosecution', '/ˌprɒsɪˈkjuːʃən/', 'noun', '{"zh-TW":["起訴；檢方"],"en":["the process of charging someone with a crime"]}', NULL, 'criminal prosecution / the prosecution rests', '[{"en":"He faces prosecution for fraud.","zh-TW":"他面臨詐欺罪的起訴。"},{"en":"The prosecution presented strong evidence.","zh-TW":"檢方提出了有力的證據。"}]', '{"verb":"prosecute","noun2":"prosecutor"}', NULL, 4, 1637),
(1638, 'prospect', '/ˈprɒspɛkt/', 'noun', '{"zh-TW":["前景；可能性","潛在客戶","前景；展望"],"en":["the possibility of future success","a potential customer"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"spect","meaning":"look (看)"}}', 'job prospects / future prospects / prospective client; career prospects / bright prospects / prospective buyer', '[{"en":"Job prospects in tech are excellent.","zh-TW":"科技業的就業前景很好。"},{"en":"We have several prospective clients.","zh-TW":"我們有幾個潛在客戶。"},{"en":"Career prospects in this field are bright.","zh-TW":"這個領域的職業前景光明。"},{"en":"We have several prospective buyers.","zh-TW":"我們有幾個潛在買家。"}]', '{"adjective":"prospective","verb":"prospect"}', NULL, 3, 1638),
(1639, 'prospectus', '/prəˈspɛktəs/', 'noun', '{"zh-TW":["公開說明書；招股書"],"en":["a printed document describing a company''s offering"]}', NULL, 'investment prospectus / issue a prospectus', '[{"en":"Read the prospectus before investing.","zh-TW":"投資前請閱讀公開說明書。"},{"en":"The company issued a prospectus for the IPO.","zh-TW":"公司為IPO發行了招股書。"}]', '{"noun":"prospectus"}', NULL, 4, 1639),
