(1641, 'protect', '/prəˈtɛkt/', 'verb', '{"zh-TW":["保護"],"en":["to keep safe from harm"]}', '{"prefix":{"text":"pro-","meaning":"in front of"},"root":{"text":"tect","meaning":"cover (覆蓋)"}}', 'protect against / protect the environment / protect rights', '[{"en":"Laws exist to protect consumers.","zh-TW":"法律的存在是為了保護消費者。"},{"en":"We must protect our intellectual property.","zh-TW":"我們必須保護智慧財產權。"}]', '{"noun":"protection, protector","adjective":"protective"}', NULL, 3, 1641),
