(1643, 'protocol', '/ˈproʊtəkɒl/', 'noun', '{"zh-TW":["協議；通訊協定"],"en":["a set of rules for transmitting data"]}', NULL, 'security protocol / communication protocol', '[{"en":"Follow the security protocol.","zh-TW":"遵循安全協議。"},{"en":"HTTP is a communication protocol.","zh-TW":"HTTP是一種通訊協定。"}]', NULL, NULL, 3, 1643),
(1644, 'proud', '/praʊd/', 'adjective', '{"zh-TW":["驕傲的；自豪的"],"en":["feeling pleasure about one''s achievements","feeling deep pleasure from one''s own achievements"]}', '{"root":{"text":"proud","meaning":"valiant (英勇)"},"logic":"源自古法語 prud（英勇的），後指對自身感到光榮。"}', 'proud of / proud moment', '[{"en":"We are proud of our team''s achievement.","zh-TW":"我們為團隊的成就感到自豪。"},{"en":"This is a proud moment for the company.","zh-TW":"這是公司引以為傲的時刻。"},{"en":"Her parents are proud of her accomplishments.","zh-TW":"她的父母為她的成就感到驕傲。"},{"en":"It was a proud moment for the whole team.","zh-TW":"這是全隊引以為傲的時刻。"}]', '{"adjective":"proud","noun":"pride","adverb":"proudly"}', NULL, 2, 1644),
(1645, 'prove', '/pruːv/', 'verb', '{"zh-TW":["證明；證實"],"en":["to show that something is true"]}', NULL, 'prove that / prove to be / prove successful', '[{"en":"The data proved our hypothesis correct.","zh-TW":"數據證明我們的假設正確。"},{"en":"The investment proved to be profitable.","zh-TW":"投資被證明是有利可圖的。"}]', '{"noun":"proof","adjective":"proven"}', NULL, 2, 1645),
