(1651, 'publish', '/ˈpʌblɪʃ/', 'verb', '{"zh-TW":["出版；發表"],"en":["to make available to the public"]}', '{"root":{"text":"publ","meaning":"people (人民)"},"suffix":{"text":"-ish","meaning":"使..."}}', 'publish a report / publish online / newly published', '[{"en":"The findings were published in a journal.","zh-TW":"研究結果發表在期刊上。"},{"en":"We will publish the results online.","zh-TW":"我們將在網上公佈結果。"}]', '{"noun":"publication, publisher, publishing"}', NULL, 3, 1651),
