(1654, 'pursue', '/pərˈsjuː/', 'verb', '{"zh-TW":["追求；追趕","追求；從事","追求"],"en":["to follow in order to catch","to seek to achieve","to follow or try to achieve","to follow or work toward"]}', '{"prefix":{"text":"pur-","meaning":"forward (向前)"},"root":{"text":"sue","meaning":"follow (跟隨)"},"logic":"向前跟隨追趕，即「追求」。"}', 'pursue a career / pursue a goal / pursue happiness; pursue a career / pursue a goal / pursue opportunities; pursue a career / pursue excellence / pursue a goal', '[{"en":"She decided to pursue a career in medicine.","zh-TW":"她決定追求醫學事業。"},{"en":"He pursued his dream of becoming a writer.","zh-TW":"他追求成為作家的夢想。"},{"en":"She decided to pursue a career in finance.","zh-TW":"她決定從事金融事業。"},{"en":"We will continue to pursue this opportunity.","zh-TW":"我們將繼續追求這機會。"},{"en":"She decided to pursue a master''s degree.","zh-TW":"她決定攻讀碩士學位。"},{"en":"The company pursues excellence in all areas.","zh-TW":"公司在所有領域追求卓越。"}]', '{"noun":"pursuit"}', NULL, 2, 1654),
(1655, 'push', '/pʊʃ/', 'verb', '{"zh-TW":["推；推動"],"en":["to press forward","to urge strongly"]}', NULL, 'push forward / push back', '[{"en":"We need to push forward with the plan.","zh-TW":"我們需要推進計畫。"},{"en":"The client pushed back on the price.","zh-TW":"客戶對價格提出了異議。"}]', '{"verb":"push","noun":"push"}', NULL, 1, 1655),
